package ara.daily;
import android.app.job.*;import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Durable payload queue; JobScheduler retries independently of the WebView and PC. */
public final class NotionDiarySync {
 private static final Object LOCK=new Object();private static final int JOB=8766,PERIODIC=8767;private static final ScheduledExecutorService IO=Executors.newSingleThreadScheduledExecutor();private static final AtomicBoolean BUSY=new AtomicBoolean();private static ScheduledFuture<?> future;
 private NotionDiarySync(){}
 private static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"notion-diary-queue.json"));}
 private static JSONObject load(Context c)throws Exception{try(InputStream in=file(c).openRead();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>16*1024*1024)throw new IOException("자동 저장 대기 데이터가 너무 큽니다.");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}catch(FileNotFoundException empty){return new JSONObject().put("items",new JSONObject());}}
 private static void save(Context c,JSONObject root)throws Exception{byte[] bytes=root.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>16*1024*1024)throw new IOException("자동 저장 대기 용량이 초과됐습니다.");AtomicFile f=file(c);FileOutputStream out=null;try{out=f.startWrite();out.write(bytes);f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("ara.diary",Context.MODE_PRIVATE);}
 public static boolean enabled(Context c){return prefs(c).getBoolean("enabled",true);}
 public static void setEnabled(Context c,boolean enabled){prefs(c).edit().putBoolean("enabled",enabled).apply();if(enabled)poke(c);else{JobScheduler j=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);j.cancel(JOB);j.cancel(PERIODIC);}}
 public static String enqueue(Context context,String text){Context c=context.getApplicationContext();try{if(text==null||text.length()>4*1024*1024)throw new IOException("기록 전송 데이터가 너무 큽니다.");JSONArray days=new JSONObject(text).getJSONArray("days");boolean changed=false;synchronized(LOCK){JSONObject root=load(c);for(int i=0;i<days.length();i++)changed|=DiaryQueue.put(root,days.getJSONObject(i));if(changed)save(c,root);}if(changed)poke(c);return "";}catch(Exception e){return e.getMessage()==null?"자동 저장 대기 기록을 저장하지 못했습니다.":e.getMessage();}}
 public static void retryNow(Context c){try{synchronized(LOCK){JSONObject root=load(c),items=DiaryQueue.items(root);Iterator<String> it=items.keys();while(it.hasNext())items.getJSONObject(it.next()).put("retryAt",0);save(c,root);}}catch(Exception ignored){}poke(c);}
 public static void initialize(Context c){if(enabled(c))poke(c);}
 public static void destinationChanged(Context context){Context c=context.getApplicationContext();IO.execute(()->{try{synchronized(LOCK){JSONObject root=load(c),items=DiaryQueue.items(root);Iterator<String> it=items.keys();while(it.hasNext())items.getJSONObject(it.next()).put("syncedTarget","").put("retryAt",0);save(c,root);}poke(c);}catch(Exception ignored){}});}
 public static void poke(Context context){Context c=context.getApplicationContext();if(!enabled(c))return;schedule(c);synchronized(NotionDiarySync.class){if(future!=null)future.cancel(false);future=IO.schedule(()->run(c),5,TimeUnit.SECONDS);}}
 private static void schedule(Context c){try{JSONObject root;synchronized(LOCK){root=load(c);}JSONObject items=DiaryQueue.items(root);boolean pending=false;Iterator<String> it=items.keys();String target=prefs(c).getString("target","");while(it.hasNext())if(DiaryQueue.pending(items.getJSONObject(it.next()),target)){pending=true;break;}JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);if(!pending){jobs.cancel(JOB);jobs.cancel(PERIODIC);return;}ComponentName component=new ComponentName(c,Job.class);jobs.schedule(new JobInfo.Builder(JOB,component).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(5000).setOverrideDeadline(60000).setPersisted(true).build());if(jobs.getPendingJob(PERIODIC)==null)jobs.schedule(new JobInfo.Builder(PERIODIC,component).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000L).setPersisted(true).build());}catch(Exception ignored){}}
 public static void run(Context context){Context c=context.getApplicationContext();if(!enabled(c)||!BUSY.compareAndSet(false,true))return;try{NotionHub hub=NotionHub.get(c);JSONObject config=hub.request(null,new JSONObject().put("op","status")),target=config.optJSONObject("target");if(!config.optBoolean("connected")||target==null)return;String targetId=target.getString("id");prefs(c).edit().putString("target",targetId).apply();JSONObject snapshot;synchronized(LOCK){snapshot=load(c);}JSONObject items=DiaryQueue.items(snapshot);List<String> dates=new ArrayList<>();Iterator<String> it=items.keys();while(it.hasNext())dates.add(it.next());Collections.sort(dates);for(String date:dates){if(!enabled(c))break;JSONObject item=items.getJSONObject(date);if(!DiaryQueue.pending(item,targetId)||item.optLong("retryAt")>System.currentTimeMillis())continue;String hash=item.getString("hash");try{JSONObject result=hub.request(null,item.getJSONObject("payload"));if(!result.optBoolean("saved")&&!result.optBoolean("skipped"))throw new IOException("노션 저장 완료를 확인하지 못했습니다.");synchronized(LOCK){JSONObject root=load(c);DiaryQueue.done(root,date,hash,targetId,System.currentTimeMillis());save(c,root);}}catch(Exception e){String error=e.getMessage()==null?"노션 자동 저장 실패":e.getMessage();synchronized(LOCK){JSONObject root=load(c);DiaryQueue.fail(root,date,hash,error.substring(0,Math.min(600,error.length())),System.currentTimeMillis());save(c,root);}if(!error.contains("생성 결과")&&!error.contains("같은 기상일")&&!error.contains("구역"))break;}}}catch(Exception e){prefs(c).edit().putString("error",e.getMessage()==null?"자동 저장 확인 실패":e.getMessage()).apply();}finally{BUSY.set(false);schedule(c);}}
 public static String status(Context c){try{JSONObject root;synchronized(LOCK){root=load(c);}JSONObject items=DiaryQueue.items(root);int pending=0;String error=root.optString("error",prefs(c).getString("error","")),target=prefs(c).getString("target","");Iterator<String> it=items.keys();while(it.hasNext()){String date=it.next();JSONObject item=items.getJSONObject(date);if(DiaryQueue.pending(item,target)){pending++;if(!item.optString("error").isEmpty())error=date+": "+item.optString("error");}}return new JSONObject().put("enabled",enabled(c)).put("busy",BUSY.get()).put("pending",pending).put("lastSyncedAt",root.optLong("lastSyncedAt")).put("lastDate",root.optString("lastDate")).put("error",error).toString();}catch(Exception e){return "{\"enabled\":true,\"error\":\"대기 기록을 읽지 못했습니다\"}";}}
 public static class Job extends JobService {@Override public boolean onStartJob(JobParameters p){IO.execute(()->{try{run(this);}finally{jobFinished(p,false);}});return true;}@Override public boolean onStopJob(JobParameters p){return true;}}
}
